function survives({ grace, preStop, longestReq, slack }) {
  const drainBudget = grace - preStop;
  const drainNeeded = longestReq + slack;
  return { ok: drainBudget >= drainNeeded, minGrace: preStop + drainNeeded };
}
const services = [
  { name: 'api', grace: 30, preStop: 5, longestReq: 12, slack: 3 },
  { name: 'export', grace: 30, preStop: 5, longestReq: 50, slack: 10 },
];
for (const s of services) {
  const r = survives(s);
  if (r.ok) console.log(s.name + ': OK');
  else console.log(s.name + ': SIGKILL, need grace >= ' + r.minGrace + 's');
}
